BEGIN;
CREATE TABLE legacy_social_history_runs(run_id uuid PRIMARY KEY REFERENCES legacy_import_runs(run_id),protocol text NOT NULL CHECK(protocol='birdtie-civu-social-history-source-v1'),source_file_sha256 text NOT NULL,manifest_file_sha256 text NOT NULL,snapshot_sha256 text NOT NULL,social_source_file_sha256 text NOT NULL,social_manifest_file_sha256 text NOT NULL,social_snapshot_sha256 text NOT NULL,projection_sha256 text NOT NULL,counts jsonb NOT NULL CHECK(birdtie_legacy_fixed_keys(counts,ARRAY['threads','messages','notifications','deletedNotifications','historicalUnread','preferences']) AND birdtie_legacy_nonnegative_counts(counts)),CHECK(source_file_sha256~'^[0-9a-f]{64}$' AND manifest_file_sha256~'^[0-9a-f]{64}$' AND snapshot_sha256~'^[0-9a-f]{64}$' AND social_source_file_sha256~'^[0-9a-f]{64}$' AND social_manifest_file_sha256~'^[0-9a-f]{64}$' AND social_snapshot_sha256~'^[0-9a-f]{64}$' AND projection_sha256~'^[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE legacy_social_history_facts(run_id uuid NOT NULL REFERENCES legacy_social_history_runs(run_id) DEFERRABLE INITIALLY DEFERRED,kind text NOT NULL CHECK(kind IN('thread','message','notification','preferences')),source_key uuid NOT NULL,source_sha256 text NOT NULL CHECK(source_sha256~'^[0-9a-f]{64}$'),target_id uuid NOT NULL,owner_account_id uuid NOT NULL REFERENCES accounts(id),PRIMARY KEY(kind,source_key),UNIQUE(kind,target_id));
CREATE TABLE personal_journey_history_threads(id uuid PRIMARY KEY,owner_account_id uuid NOT NULL REFERENCES accounts(id),journey_id uuid REFERENCES journeys(id),source_journey_id uuid,source_draft_context_id uuid,summary text NOT NULL CHECK(octet_length(summary)<=32768),state text NOT NULL DEFAULT 'HISTORICAL' CHECK(state='HISTORICAL'),source_status text NOT NULL,source_context_revision bigint NOT NULL,source_created_at timestamptz NOT NULL,source_updated_at timestamptz NOT NULL,CHECK(num_nonnulls(source_journey_id,source_draft_context_id)=1));
CREATE INDEX personal_journey_history_owner ON personal_journey_history_threads(owner_account_id,source_updated_at DESC,id DESC);
CREATE TABLE personal_journey_history_messages(id uuid PRIMARY KEY,history_thread_id uuid NOT NULL REFERENCES personal_journey_history_threads(id),role text NOT NULL CHECK(role IN('USER','ASSISTANT')),body text NOT NULL CHECK(octet_length(body)<=32768),source_request_id text NOT NULL CHECK(octet_length(source_request_id)<=1024),source_created_at timestamptz NOT NULL);
CREATE INDEX personal_journey_history_order ON personal_journey_history_messages(history_thread_id,source_created_at,id);
CREATE TABLE historical_notification_facts(id uuid PRIMARY KEY,owner_account_id uuid NOT NULL REFERENCES accounts(id),actor_account_id uuid REFERENCES accounts(id),original_type text NOT NULL,event_type text NOT NULL,source_category text NOT NULL,source_target_kind text NOT NULL,source_target_id uuid,native_target_kind text,native_target_id uuid,source_anchor_kind text NOT NULL,source_anchor_id uuid,original_action text NOT NULL,source_created_at timestamptz NOT NULL,source_read_at timestamptz,source_seen_at timestamptz,source_deleted_at timestamptz,payload_schema_version bigint NOT NULL,source_inbox_version bigint NOT NULL,residual_keys text[] NOT NULL);
CREATE TABLE personal_notification_preferences(id uuid PRIMARY KEY,owner_account_id uuid NOT NULL UNIQUE REFERENCES accounts(id),chat_push boolean NOT NULL,request_push boolean NOT NULL,comment_push boolean NOT NULL,follow_push boolean NOT NULL,praise_save_push boolean NOT NULL,journey_push boolean NOT NULL,system_push boolean NOT NULL,preview_enabled boolean NOT NULL,collaboration_push boolean,time_zone text NOT NULL,quiet_start text NOT NULL,quiet_end text NOT NULL,source_version bigint NOT NULL,source_updated_at timestamptz NOT NULL);
ALTER TABLE inbox_items ADD COLUMN origin text NOT NULL DEFAULT 'NATIVE' CHECK(origin IN('NATIVE','LEGACY_HISTORY'));
ALTER TABLE inbox_items DROP CONSTRAINT inbox_items_resource_type_check;
ALTER TABLE inbox_items ADD CONSTRAINT inbox_items_resource_type_check CHECK(resource_type IN('place_candidate','activity_candidate','community','connection_request','conversation_message','activity_change','activity_cancelled','activity_reminder','community_message','activity_message','organization_membership','agent_task','opportunity_available','business_claim_review','business_update','moment_like','moment_comment','legacy_history'));
ALTER TABLE inbox_items ADD CONSTRAINT inbox_legacy_history_shape CHECK((origin='LEGACY_HISTORY')=(resource_type='legacy_history') AND(origin<>'LEGACY_HISTORY' OR(routing_decision_id IS NULL AND target_activity_id IS NULL AND target_conversation_id IS NULL)));
CREATE FUNCTION birdtie_check_legacy_history_fact()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
IF NOT EXISTS(SELECT 1 FROM legacy_social_history_runs r JOIN legacy_social_import_runs s ON s.run_id=r.run_id AND s.source_file_sha256=r.social_source_file_sha256 AND s.manifest_file_sha256=r.social_manifest_file_sha256 AND s.snapshot_sha256=r.social_snapshot_sha256 JOIN legacy_entity_mappings u ON u.run_id=r.run_id AND u.entity_kind='user' AND u.target_id=NEW.owner_account_id AND u.owner_account_id=NEW.owner_account_id WHERE r.run_id=NEW.run_id)THEN RAISE EXCEPTION 'exact preserved history owner/source required';END IF;
IF NEW.kind='thread' AND NOT EXISTS(SELECT 1 FROM personal_journey_history_threads t WHERE t.id=NEW.target_id AND t.owner_account_id=NEW.owner_account_id)OR NEW.kind='message' AND NOT EXISTS(SELECT 1 FROM personal_journey_history_messages m JOIN personal_journey_history_threads t ON t.id=m.history_thread_id WHERE m.id=NEW.target_id AND t.owner_account_id=NEW.owner_account_id)OR NEW.kind='notification' AND NOT EXISTS(SELECT 1 FROM historical_notification_facts n WHERE n.id=NEW.target_id AND n.owner_account_id=NEW.owner_account_id)OR NEW.kind='preferences' AND NOT EXISTS(SELECT 1 FROM personal_notification_preferences p WHERE p.id=NEW.target_id AND p.owner_account_id=NEW.owner_account_id)THEN RAISE EXCEPTION 'exact native history target required';END IF;RETURN NULL;END$$;
CREATE CONSTRAINT TRIGGER legacy_history_source_binding AFTER INSERT ON legacy_social_history_facts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION birdtie_check_legacy_history_fact();
CREATE FUNCTION birdtie_legacy_history_counts()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE actual jsonb;BEGIN SELECT jsonb_build_object('threads',count(*)FILTER(WHERE kind='thread'),'messages',count(*)FILTER(WHERE kind='message'),'notifications',count(*)FILTER(WHERE kind='notification'),'preferences',count(*)FILTER(WHERE kind='preferences'),'deletedNotifications',(SELECT count(*)FROM historical_notification_facts n JOIN legacy_social_history_facts f ON f.kind='notification' AND f.target_id=n.id WHERE f.run_id=NEW.run_id AND n.source_deleted_at IS NOT NULL),'historicalUnread',(SELECT count(*)FROM historical_notification_facts n JOIN legacy_social_history_facts f ON f.kind='notification' AND f.target_id=n.id WHERE f.run_id=NEW.run_id AND n.source_deleted_at IS NULL AND n.source_read_at IS NULL))INTO actual FROM legacy_social_history_facts WHERE run_id=NEW.run_id;IF actual<>NEW.counts THEN RAISE EXCEPTION 'exact original history counts required';END IF;RETURN NULL;END$$;
CREATE CONSTRAINT TRIGGER legacy_history_counts AFTER INSERT ON legacy_social_history_runs DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION birdtie_legacy_history_counts();
CREATE TRIGGER legacy_history_run_immutable BEFORE UPDATE OR DELETE ON legacy_social_history_runs FOR EACH ROW EXECUTE FUNCTION birdtie_legacy_immutable();
CREATE TRIGGER legacy_history_facts_immutable BEFORE UPDATE OR DELETE ON legacy_social_history_facts FOR EACH ROW EXECUTE FUNCTION birdtie_legacy_immutable();
CREATE TRIGGER historical_threads_immutable BEFORE UPDATE OR DELETE ON personal_journey_history_threads FOR EACH ROW EXECUTE FUNCTION birdtie_legacy_immutable();
CREATE TRIGGER historical_messages_immutable BEFORE UPDATE OR DELETE ON personal_journey_history_messages FOR EACH ROW EXECUTE FUNCTION birdtie_legacy_immutable();
CREATE TRIGGER historical_notifications_immutable BEFORE UPDATE OR DELETE ON historical_notification_facts FOR EACH ROW EXECUTE FUNCTION birdtie_legacy_immutable();
CREATE TRIGGER original_preferences_immutable BEFORE UPDATE OR DELETE ON personal_notification_preferences FOR EACH ROW EXECUTE FUNCTION birdtie_legacy_immutable();
CREATE FUNCTION birdtie_guard_historical_inbox()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.origin='LEGACY_HISTORY' AND NOT EXISTS(SELECT 1 FROM historical_notification_facts n JOIN legacy_social_history_facts f ON f.kind='notification' AND f.target_id=n.id WHERE n.id=NEW.id AND NEW.resource_id=n.id AND n.owner_account_id=NEW.recipient_account_id AND n.source_deleted_at IS NULL AND NEW.created_at=n.source_created_at AND NEW.read_at IS NOT DISTINCT FROM n.source_read_at)THEN RAISE EXCEPTION 'exact inert original notification required';END IF;RETURN NEW;END$$;
CREATE TRIGGER historical_inbox_insert BEFORE INSERT ON inbox_items FOR EACH ROW EXECUTE FUNCTION birdtie_guard_historical_inbox();
CREATE FUNCTION birdtie_legacy_history_contract()RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT 'legacy-social-history-v1'::text$$;
COMMENT ON TABLE personal_journey_history_messages IS 'Private historical USER/ASSISTANT text only; never Agent, Memory, model context, a pending command or provider task.';
COMMENT ON COLUMN inbox_items.origin IS 'LEGACY_HISTORY never has routing_decision_id, delivery, push or current unread badge semantics.';
COMMIT;
